"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[73955],{28453:(e,n,s)=>{s.d(n,{R:()=>o,x:()=>r});var t=s(96540);const i={},a=t.createContext(i);function o(e){const n=t.useContext(a);return t.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),t.createElement(a.Provider,{value:n},e.children)}},53276:(e,n,s)=>{s.r(n),s.d(n,{assets:()=>h,contentTitle:()=>r,default:()=>l,frontMatter:()=>o,metadata:()=>t,toc:()=>c});const t=JSON.parse('{"id":"tangfen/tosiwen","title":"","description":"This [Siwen], in \\"\'Suspected of perjury\' as said by Ch\xe1n Zh\u014dng Shu\u014d Ch\xe1n IS \'the crime of perjury\' -- Reply to Tangfen,\\" continues his habitual groundless fabrication. Quoted as follows:","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/tosiwen.md","sourceDirName":"tangfen","slug":"/tangfen/tosiwen","permalink":"/tangfen/tosiwen","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"tosiwen","title":"","hide_table_of_contents":true},"sidebar":"tangfenSidebar","previous":{"title":"\u4e00\u5802\u5e7c\u513f\u56ed\u7269\u7406\u8bfe\uff0c\u518d\u7ed9\u4e91\u8c37\u5b50\u4e4b\u6d41\uff01","permalink":"/tangfen/abasicphysicslecture"},"next":{"title":"\u601d\u95fb\uff0c\u8c01\u544a\u8bc9\u4f60\u7f20\u5973\u58eb\u7684\u6d89\u5acc\u4f2a\u8bc1\u5c31\u662f\u4f60\u8bf4\u7684\u201c\u4f2a\u8bc1\u7f6a\u201d\uff1f","permalink":"/tangfen/tosiwen2"}}');var i=s(74848),a=s(28453);const o={id:"tosiwen",title:"",hide_table_of_contents:!0},r="[Siwen], Don't Make a Habit of Groundless Fabrication When Discussing Issues!",h={},c=[];function u(e){const n={h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"siwen-dont-make-a-habit-of-groundless-fabrication-when-discussing-issues",children:"[Siwen], Don't Make a Habit of Groundless Fabrication When Discussing Issues!"})}),"\n",(0,i.jsx)(n.p,{children:"This [Siwen], in \"'Suspected of perjury' as said by Ch\xe1n Zh\u014dng Shu\u014d Ch\xe1n IS 'the crime of perjury' -- Reply to Tangfen,\" continues his habitual groundless fabrication. Quoted as follows:"}),"\n",(0,i.jsxs)(n.p,{children:["\"Ch\xe1n Zh\u014dng Shu\u014d Ch\xe1n published opinions based on the information disclosed at that press conference, determining that Gao Tianhu 'is suspected of perjury!' and repeatedly proposing to resolve the matter through 'legal procedures.' Since we are discussing a criminal matter, and criminal matters deal with suspected crimes rather than shortcomings or mistakes, when Ch\xe1n Zh\u014dng Shu\u014d Ch\xe1n says Gao Tianhu 'is suspected of perjury!,' she is of course saying he 'is suspected of the crime of perjury,' not that he is suspected of making a false testimony as an error.\" ",(0,i.jsx)("br",{}),"\n======= ",(0,i.jsx)("br",{}),'\nBut please look at what Miss Chan means by "legal procedures," quoted as follows:']}),"\n",(0,i.jsx)(n.p,{children:"\"Now these underpants bearing Gao Tianhu's own semen stain have become the most powerful evidence. There are two possibilities: one is that Gao Tianhu was forced to leave the semen stain; the other is that he was not forced. The meaningful premise of these two possibilities is that 'the semen stain was left by Gao Tianhu himself' is factual. Whether this is fact can be verified quite normally and seriously. Therefore, finding an authoritative institution or even a non-governmental organization to confirm this fact is the best method of verification."}),"\n",(0,i.jsx)(n.p,{children:'Once this fact is confirmed again, and if Gao Tianhu was not forced to leave the semen stain, then the only reasonable explanation for his underpants bearing his own semen stain is that he is suspected of fabricating evidence! Therefore, the current issues can all be resolved within legal procedures. There is no need for this kind of public clamor. What significance does this clamor have? Other than letting certain people vent, or even allowing some unspeakable designs to continue, it is completely meaningless."'}),"\n",(0,i.jsx)(n.p,{children:'One can clearly see that Miss Chan\'s "legal procedure" here refers to going through legal procedures to verify whether "the underpants bearing Gao Tianhu\'s own semen stain" are as claimed. Moreover, to emphasize this point, Miss Chan stressed at the end of her post: "Now, through legal procedures, if anyone questions \'the semen stain being left by Gao Tianhu himself,\' they can raise the question through legal procedures and seek re-examination. Anything beyond this is superfluous and ill-intentioned!" Anyone who reads Chinese knows what "raising questions through legal procedures and seeking re-examination" means.'}),"\n",(0,i.jsx)(n.p,{children:"So Siwen slandering Miss Chan by saying \"she repeatedly proposed resolving things through 'legal procedures.' Since we are discussing a criminal matter, and criminal matters deal with suspected crimes... when Ch\xe1n Zh\u014dng Shu\u014d Ch\xe1n says Gao Tianhu 'is suspected of perjury!,' she is of course saying he 'is suspected of the crime of perjury'\" is a deliberate distortion of Miss Chan's meaning!"}),"\n",(0,i.jsx)(n.p,{children:"Moreover, the context of Miss Chan's post is absolutely not premised on Gao's father having committed a crime. The entire meaning of Miss Chan's post revolves around the verification of those underpants -- the point being that whether there's an issue with the underpants can be resolved through legal procedures. This is clearly evident from the last paragraph of Miss Chan's post: \"Now, through legal procedures, if anyone questions 'the semen stain being left by Gao Tianhu himself,' they can raise the question through legal procedures and seek re-examination. Anything beyond this is superfluous and ill-intentioned!\" So Siwen saying \"Miss Chan's 'suspected of perjury' was originally intended as 'suspected of the crime of perjury'\" is a thorough fabrication!"})]})}function l(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(u,{...e})}):u(e)}}}]);